<?php
declare(strict_types=1); namespace App\Command;
use App\Entity\User; use Doctrine\ORM\EntityManagerInterface; use Symfony\Component\Console\Attribute\AsCommand; use Symfony\Component\Console\Command\Command; use Symfony\Component\Console\Input\InputArgument; use Symfony\Component\Console\Input\InputInterface; use Symfony\Component\Console\Input\InputOption; use Symfony\Component\Console\Output\OutputInterface; use Symfony\Component\PasswordHasher\Hasher\UserPasswordHasherInterface;
#[AsCommand(name:'app:user:create-admin',description:'Legt den ersten Administrator an.')] final class CreateAdminCommand extends Command {public function __construct(private EntityManagerInterface $em,private UserPasswordHasherInterface $hasher){parent::__construct();} protected function configure():void{$this->addArgument('email',InputArgument::REQUIRED)->addArgument('first-name',InputArgument::REQUIRED)->addArgument('last-name',InputArgument::REQUIRED)->addOption('password',null,InputOption::VALUE_REQUIRED);} protected function execute(InputInterface $i,OutputInterface $o):int{$password=(string)$i->getOption('password');if(strlen($password)<12){$o->writeln('<error>--password muss mindestens 12 Zeichen lang sein.</error>');return self::INVALID;}$u=(new User())->setEmail((string)$i->getArgument('email'))->setFirstName((string)$i->getArgument('first-name'))->setLastName((string)$i->getArgument('last-name'))->setRoles(['ROLE_ADMIN'])->setPermissions([User::PERMISSION_NEWS,User::PERMISSION_TRAINING,User::PERMISSION_EVENTS]);$u->setPassword($this->hasher->hashPassword($u,$password));$this->em->persist($u);$this->em->flush();$o->writeln('<info>Administrator angelegt.</info>');return self::SUCCESS;}}
